package main

import (
    "fmt"
    "sync"
    "time"
)

func worker(id int, wg *sync.WaitGroup) {
    defer wg.Done()
    fmt.Printf("워커 %d 시작\n", id)
    time.Sleep(50 * time.Millisecond)
    fmt.Printf("워커 %d 작업 완료\n", id)
}

func main() {
    var wg sync.WaitGroup

    // 5개의 경량 고루틴 동시 실행
    for i := 1; i <= 5; i++ {
        wg.Add(1)
        go worker(i, &wg)
    }

    // 모든 고루틴이 작업을 마칠 때까지 대기
    wg.Wait()
    fmt.Println("모든 고루틴 작업 완료")
}

